  if (m4 === 'wOF2') return 'woff2';
  if (m4 === 'OTTO' || m4 === 'true' || m4 === 'ttcf' || (b[0] === 0 && b[1] === 1 && b[2] === 0 && b[3] === 0)) return 'ttf';
  if (text(b.subarray(0, 9)) === 'STARTFONT') return 'bdf';
